package com.lebzlon.measurementtracker.service;

import com.lebzlon.measurementtracker.dto.Dtos.*; import com.lebzlon.measurementtracker.entity.*; import com.lebzlon.measurementtracker.exception.*; import com.lebzlon.measurementtracker.repository.*; import com.lebzlon.measurementtracker.security.JwtService; import jakarta.transaction.Transactional; import org.springframework.security.authentication.*; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile;
import java.awt.*; import java.awt.image.BufferedImage; import java.io.*; import java.math.BigDecimal; import java.nio.file.*; import java.time.Instant; import java.util.*; import java.util.regex.*; import javax.imageio.ImageIO;

@Service class UserService { private final UserRepository repo; private final PasswordEncoder enc; UserService(UserRepository r,PasswordEncoder e){repo=r;enc=e;} User current(){String u=SecurityContextHolder.getContext().getAuthentication().getName(); return repo.findByUsername(u).orElseThrow(()->new NotFoundException("User not found"));} UserResponse me(){var u=current(); return new UserResponse(u.getId(),u.getUsername(),u.getCreatedAt());} User register(RegisterRequest r){ if(repo.existsByUsername(r.username())) throw new ApiException("Duplicate username"); User u=new User(); u.setUsername(r.username()); u.setPassword(enc.encode(r.password())); return repo.save(u);} }
@Service class AuthService { private final AuthenticationManager am; private final JwtService jwt; private final UserService users; AuthService(AuthenticationManager a, JwtService j, UserService u){am=a;jwt=j;users=u;} AuthResponse register(RegisterRequest r){users.register(r); return login(new LoginRequest(r.username(),r.password()));} AuthResponse login(LoginRequest r){ am.authenticate(new UsernamePasswordAuthenticationToken(r.username(),r.password())); return new AuthResponse(jwt.generate(r.username())); }}
@Service class MeterService { private final MeterRepository repo; private final UserService us; MeterService(MeterRepository r, UserService u){repo=r;us=u;} MeterResponse create(MeterRequest req){ if(repo.existsBySerialNumber(req.serialNumber())) throw new ApiException("Duplicate serial"); Meter m=new Meter(); m.setSerialNumber(req.serialNumber()); m.setType(req.type()); m.setTitle(req.title()); m.setUser(us.current()); return map(repo.save(m)); } List<MeterResponse> list(){return repo.findByUserAndActiveTrue(us.current()).stream().map(this::map).toList();} Meter owned(Long id){return repo.findByIdAndUser(id,us.current()).orElseThrow(()->new NotFoundException("Meter not found"));} MeterResponse one(Long id){return map(owned(id));} MeterResponse update(Long id,MeterRequest req){Meter m=owned(id); m.setTitle(req.title()); m.setType(req.type()); return map(repo.save(m));} void delete(Long id){Meter m=owned(id); m.setActive(false); repo.save(m);} private MeterResponse map(Meter m){return new MeterResponse(m.getId(),m.getSerialNumber(),m.getType(),m.getTitle(),m.isActive());}}
@Service class ReadingService { private final MeterReadingRepository repo; private final MeterService meters; private final UserService us; ReadingService(MeterReadingRepository r,MeterService m,UserService u){repo=r;meters=m;us=u;} @Transactional ReadingResponse addManual(ManualReadingRequest req){ MeterReading mr=new MeterReading(); mr.setMeter(meters.owned(req.meterId())); mr.setTimestamp(req.timestamp()); mr.setValue(req.value()); mr.setSource(ReadingSource.MANUAL); return map(repo.save(mr)); } List<ReadingResponse> list(){return repo.findByMeterUserOrderByTimestampDesc(us.current()).stream().map(this::map).toList();} ReadingResponse one(Long id){return map(repo.findByIdAndMeterUser(id,us.current()).orElseThrow(()->new NotFoundException("Reading not found")));} List<ReadingResponse> byMeter(Long id){meters.owned(id); return repo.findByMeterIdAndMeterUserOrderByTimestampDesc(id,us.current()).stream().map(this::map).toList();} List<ReadingResponse> history(Long m, Instant f, Instant t){meters.owned(m); return repo.history(m,us.current(),f,t).stream().map(this::map).toList();} ReadingResponse map(MeterReading r){return new ReadingResponse(r.getId(),r.getMeter().getId(),r.getTimestamp(),r.getValue(),r.getSource(),r.getImagePath(),r.getOcrRawText());}}
@Service class OcrService { String run(String tesseract,Path file) throws Exception { Process p = new ProcessBuilder(tesseract,file.toString(),"stdout").start(); if(p.waitFor()!=0) throw new ApiException("Tesseract failed"); return new String(p.getInputStream().readAllBytes()); } BigDecimal extractValue(String raw){ Matcher m=Pattern.compile("(\\d+[\\.,]?\\d*)").matcher(raw.replace('\n',' ')); BigDecimal best=null; while(m.find()){ BigDecimal c=new BigDecimal(m.group(1).replace(',','.')); if(best==null||c.compareTo(best)>0) best=c;} if(best==null) throw new ApiException("Cannot extract value"); return best; }}
@Service class FileStorageService { private final Path orig=Path.of("uploads/original"); private final Path proc=Path.of("uploads/processed"); FileStorageService() throws IOException {Files.createDirectories(orig); Files.createDirectories(proc);} Path saveOriginal(MultipartFile f) throws IOException{ if(f.isEmpty()) throw new ApiException("Empty file"); if(!List.of("image/png","image/jpeg").contains(f.getContentType())) throw new ApiException("Bad mime"); String n=UUID.randomUUID()+"-"+Objects.requireNonNull(f.getOriginalFilename()).replaceAll("[^a-zA-Z0-9._-]","_"); Path p=orig.resolve(n).normalize(); if(!p.startsWith(orig)) throw new ApiException("Path traversal"); Files.copy(f.getInputStream(),p,StandardCopyOption.REPLACE_EXISTING); return p;} Path preprocess(Path src) throws IOException { BufferedImage in=ImageIO.read(src.toFile()); int w=in.getWidth(),h=in.getHeight(); BufferedImage crop=in.getSubimage(0,h/3,w,h/3); BufferedImage out=new BufferedImage(crop.getWidth(),crop.getHeight(),BufferedImage.TYPE_BYTE_GRAY); Graphics2D g=out.createGraphics(); g.drawImage(crop,0,0,null); g.dispose(); Path p=proc.resolve("proc-"+src.getFileName()+".png"); ImageIO.write(out,"png",p.toFile()); return p; }}
@Service class OcrTaskService { private final OcrTaskRepository repo; private final MeterService meters; private final UserService us; private final FileStorageService files; OcrTaskService(OcrTaskRepository r,MeterService m,UserService u,FileStorageService f){repo=r;meters=m;us=u;files=f;} OcrTaskResponse create(Long meterId, Instant ts, MultipartFile file) throws IOException{ Path path=files.saveOriginal(file); OcrTask t=new OcrTask(); t.setMeter(meters.owned(meterId)); t.setTimestamp(ts); t.setImagePath(path.toString()); t.setStatus(OcrTaskStatus.NEW); return map(repo.save(t)); } List<OcrTaskResponse> list(){return repo.findByMeterUserOrderByCreatedAtDesc(us.current()).stream().map(this::map).toList();} OcrTaskResponse one(Long id){return map(repo.findByIdAndMeterUser(id,us.current()).orElseThrow(()->new NotFoundException("Task not found")));} OcrTaskResponse map(OcrTask t){return new OcrTaskResponse(t.getId(),t.getMeter().getId(),t.getImagePath(),t.getTimestamp(),t.getStatus(),t.getOcrRawText(),t.getExtractedValue(),t.getErrorMessage());}}
